const telegramData = $("Telegram Trigger1").all();
const documentExtensions = [".pdf", ".doc", ".docx", ".xlsx"];
const imageExtensions = [".jpg", ".jpeg", ".webp"];

const result = telegramData.map((item) => {
  const msg = item.json.message || {};

  let extension = null;

  if (msg.document?.file_name) {
    // Document → extract extension from filename
    extension = "." + msg.document.file_name.split(".").pop().toLowerCase();
  } else if (msg.photo) {
    // Photo → default extension
    extension = ".jpg";
  }

  const classification =
    (documentExtensions.includes(extension) || imageExtensions.includes(extension))
      ? "file"
      : "other";

  return { json: { extension, classification } };
});

return result;

const items = $input.all();

// List of valid U.S. tax-related document types
const validDocuments = [
  "ID (Driver's License or Passport)",
  "Social Security Document",
  "W-2 Form",
  "1099 Form",
  "Bank Statement",
  "Business Income/Expense Summary",
  "Last Year's Tax Return",
  "Receipt (any type)"
];

const documentData = items.map((item) => {
  const rawText =
    item?.json?.content?.[0]?.text ||
    item?.json?.response ||
    item?.json?.text ||
    "";

  const cleaned = rawText
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();

  let parsed;
  try {
    parsed = JSON.parse(cleaned);
  } catch (err) {
    console.error("Failed to parse JSON:", err);
    return {
      documentType: "Unknown",
      reason: "unknown",
      confidence: 0
    };
  }

  let { documentType, reason, confidence } = parsed;

  // If the detected type is not in the valid list, override to unknown
  if (!validDocuments.includes(documentType)) {
    documentType = "Unknown";
    reason = "unknown";
  }

  return {
    documentType: documentType ?? "Unknown",
    reason: reason ?? "unknown",
    confidence: confidence ?? 0
  };
});

return { json: { documentData } };

