const items = $input.all();
const formattedItems = items.map((item) => {
  try {
    const aiResponse = item.json.output;
    const codeBlockMatch = aiResponse.match(/```json([\s\S]*?)```/);
    let jsonString = aiResponse;

    if (codeBlockMatch) {
      jsonString = codeBlockMatch[1].trim();
    }

    const parsed = JSON.parse(jsonString);
    const missingString = Array.isArray(parsed.missing_fields)
      ? parsed.missing_fields.join(", ")
      : "";

    return {
      json: {
        status: parsed.status || null,
        missing_fields: missingString,
      },
    };
  } catch (error) {
    console.error(error);
    return {
      json: {
        status: null,
        missing_fields: "",
        error: error.message,
      },
    };
  }
});

return formattedItems;

// Helper function to check if a value is empty
const isEmpty = (value) => {
  return value === null || 
         value === undefined || 
         (typeof value === 'string' && value.trim() === '') ||
         (typeof value === 'number' && isNaN(value));
};

const results = [];

for (const inputItem of $input.all()) {
  const item = inputItem.json;

  // Find Telegram ID column (case-insensitive)
  const telegramIdKey = Object.keys(item).find(
    key => key.toLowerCase() === 'telegram id'
  ) || 'Telegram ID';

  // Skip rows without Telegram ID
  if (!item[telegramIdKey] || isEmpty(item[telegramIdKey])) {
    continue;
  }

  // Get all column names except Telegram ID and row_number
  const allColumns = Object.keys(item);
  const missingColumns = [];

  for (const column of allColumns) {
    const columnLower = column.toLowerCase();

    // Skip Telegram ID and row_number columns
    if (columnLower !== 'telegram id' && column !== 'row_number') {
      const value = item[column];
      if (isEmpty(value)) {
        missingColumns.push(column);
      }
    }
  }

  // Only push if there are missing columns
  if (missingColumns.length > 0) {
    results.push({
      json: {
        row_number: item.row_number,
        telegram_id: item[telegramIdKey],
        name: item.Name,
        missing_columns: missingColumns.join(", "), // ✅ single string
        total_missing: missingColumns.length
      }
    });
  }
}

return results;
